class TrafficLight07{private String color="RED";private final String id;TrafficLight07(String i){id=i;}void next(){color=color.equals("RED")?"GREEN":color.equals("GREEN")?"YELLOW":"RED";}String getColor(){return color;}String getId(){return id;}} public class Week07Problem04{public static void main(String[]z){TrafficLight07 t=new TrafficLight07("TL-01");for(int i=0;i<4;i++){System.out.println(t.getId()+": "+t.getColor());t.next();}}}